import{_ as a,c as o,o as n,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"NoSQL Databases, MongoDB, and Mongoose — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-07-mongodb-mongoose.md","filePath":"practice/node-js/module-07-mongodb-mongoose.md"}'),t={name:"practice/node-js/module-07-mongodb-mongoose.md"};function s(r,e,l,d,c,p){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="nosql-databases-mongodb-and-mongoose-—-practice" tabindex="-1">NoSQL Databases, MongoDB, and Mongoose — practice <a class="header-anchor" href="#nosql-databases-mongodb-and-mongoose-—-practice" aria-label="Permalink to “NoSQL Databases, MongoDB, and Mongoose — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-07-mongodb-mongoose.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="diagnostic-exercise" tabindex="-1"><span class="hub-section-number">1 </span>Diagnostic exercise <a class="header-anchor" href="#diagnostic-exercise" aria-label="Permalink to “1 Diagnostic exercise”">​</a></h3><p>Create an inventory reservation workflow.</p><p>Prove that:</p><ul><li>stock never becomes negative under concurrent requests;</li><li>duplicate order commands return one logical result;</li><li>the query uses the intended index;</li><li>transaction retries do not duplicate external side effects;</li><li>a schema backfill can stop and resume;</li><li>pool saturation fails within a bounded time instead of hanging indefinitely.</li></ul><hr><h2 id="_21-final-review-checklist" tabindex="-1"><span class="hub-section-number">2 </span>Final review checklist <a class="header-anchor" href="#_21-final-review-checklist" aria-label="Permalink to “2 Final review checklist”">​</a></h2><h3 id="concurrency-and-operations" tabindex="-1"><span class="hub-section-number">2.1 </span>Concurrency and operations <a class="header-anchor" href="#concurrency-and-operations" aria-label="Permalink to “2.1 Concurrency and operations”">​</a></h3><ul><li>[ ] Replace unsafe read-modify-write code with atomic conditional updates where possible.</li><li>[ ] Use optimistic concurrency when conflicting overwrites must be detected.</li><li>[ ] Keep multi-document transactions short and free of external side effects.</li><li>[ ] Explain read concern, write concern, read preference, and stale-read consequences.</li><li>[ ] Evolve document shapes with compatible readers, new writers, and resumable backfills.</li><li>[ ] Separate pool wait time from query execution time during diagnosis.</li></ul><h3 id="nosql-selection" tabindex="-1"><span class="hub-section-number">2.2 </span>NoSQL selection <a class="header-anchor" href="#nosql-selection" aria-label="Permalink to “2.2 NoSQL selection”">​</a></h3><ul><li>[ ] Explain document, key-value, wide-column, and graph models.</li><li>[ ] Choose a database from data shape, access patterns, and guarantees.</li><li>[ ] Compare relational and document models without relying on slogans.</li><li>[ ] Explain why production systems sometimes use multiple database types.</li></ul><h3 id="mongodb" tabindex="-1"><span class="hub-section-number">2.3 </span>MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to “2.3 MongoDB”">​</a></h3><ul><li>[ ] Explain databases, collections, documents, BSON, and <code>_id</code>.</li><li>[ ] Validate and construct ObjectIds safely.</li><li>[ ] Use <code>mongosh</code> or Compass to explore data.</li><li>[ ] Design single-field, unique, and compound indexes from queries.</li><li>[ ] Explain index costs and the compound-index left-prefix rule.</li></ul><h3 id="mongoose" tabindex="-1"><span class="hub-section-number">2.4 </span>Mongoose <a class="header-anchor" href="#mongoose" aria-label="Permalink to “2.4 Mongoose”">​</a></h3><ul><li>[ ] Distinguish schema, model, document, query, and repository.</li><li>[ ] Connect before listening and disconnect during shutdown/tests.</li><li>[ ] Implement CRUD, filters, projections, sorting, and pagination.</li><li>[ ] Use <code>lean()</code> for appropriate read-only queries.</li><li>[ ] Use safe update operators and <code>runValidators</code>.</li><li>[ ] Classify validation, cast, duplicate-key, and unexpected errors.</li><li>[ ] Explain document hooks versus query hooks.</li><li>[ ] Build aggregation pipelines with ordered stages.</li></ul><h3 id="data-modeling" tabindex="-1"><span class="hub-section-number">2.5 </span>Data modeling <a class="header-anchor" href="#data-modeling" aria-label="Permalink to “2.5 Data modeling”">​</a></h3><ul><li>[ ] Embed small, bounded, owned data that is read with its parent.</li><li>[ ] Reference shared, independent, or unbounded data.</li><li>[ ] Account for the 16 MiB document limit and array growth.</li><li>[ ] Resolve references with <code>populate()</code> or <code>$lookup</code> deliberately.</li><li>[ ] Plan referential integrity and deletion behavior in application workflows.</li></ul><h3 id="distributed-system-theory" tabindex="-1"><span class="hub-section-number">2.6 </span>Distributed-system theory <a class="header-anchor" href="#distributed-system-theory" aria-label="Permalink to “2.6 Distributed-system theory”">​</a></h3><ul><li>[ ] Define CAP consistency, availability, and partition tolerance.</li><li>[ ] Explain why the C/A trade-off matters specifically during a partition.</li><li>[ ] Avoid treating CP/AP labels as immutable database identities.</li><li>[ ] Define ACID and BASE.</li><li>[ ] Distinguish ACID consistency from CAP consistency.</li><li>[ ] Explain why SQL/NoSQL and ACID/BASE are not exact synonyms.</li></ul><h2 id="model-lifecycle-and-update-acceptance-labs" tabindex="-1"><span class="hub-section-number">3 </span>Model, lifecycle and update acceptance labs <a class="header-anchor" href="#model-lifecycle-and-update-acceptance-labs" aria-label="Permalink to “3 Model, lifecycle and update acceptance labs”">​</a></h2><p>Primary backend study stack remains PostgreSQL; MongoDB/Mongoose is the document-model alternative. Examples here use Mongoose9.11.2/Node24.18.0 for the local schema/control-flow checks; verify server compatibility separately. Do not assume an offline schema test exercises a MongoDB server.</p><p><strong>Model consistency:</strong> validate user/editor/country/loginCount examples against the declared main schema; confirm invalid roles/negative or fractional loginCount fail on document validation. Understand that $inc query update validators do not enforce every numeric invariant: protect critical increments with validated operations/conditional filters, and database validation where required. Base author population works with the declared ref; nested reviewer/team needs its explicit model variant. Aggregation country comes from the top-level declared field, with a documented missing-country policy.</p><p><strong>Bounded comments:</strong> create a valid small post; document validation rejects over100 embedded comments and overlong text. The update path must use $each+$slice:-100, so repeated/concurrent writes preserve at most the recent100 snapshot. Keep full history in a separate paginated collection when required. Test other writers/database validation and maximum BSON size separately; a Mongoose array validator alone does not guarantee every query update is bounded.</p><p><strong>Inventory:</strong> reject0, negatives, fractions, nonnumbers, Infinity and unsafe integers before decrementing stock or beginning the transaction. A negative decrement would otherwise increase stock. Race two valid reservations against the real conditional filter and require nonnegative remaining stock/one accepted reservation when capacity fits only one. Declare the Product stock/version fields and verify transaction-capable topology and outbox schemas before treating the snippets as a complete service.</p><p><strong>Migration and lifecycle:</strong> use only legacy_users fixtures for this backfill, verify declared displayName survives strict casting and a missing destination field fails loudly; test empty/completed/bounded/resumed/invalid-name/no-progress/partial-error/cancel cases. Trigger HTTP-close and disconnect failures and require one awaited rejected cleanup result, no unhandled rejection and no second disconnect on repeated signals. Real Mongo transaction/index/pool/startup/shutdown deadlines and learner practice remain separate required evidence.</p><p>References checked2026-10-21: <a href="https://mongoosejs.com/docs/guide.html#strict" target="_blank" rel="noreferrer">Mongoose strict schema</a>, <a href="https://mongoosejs.com/docs/validation.html#update-validators" target="_blank" rel="noreferrer">update validator limits</a>, <a href="https://www.mongodb.com/docs/manual/core/write-operations-atomicity/" target="_blank" rel="noreferrer">Mongo atomicity</a>, <a href="https://www.mongodb.com/docs/manual/reference/operator/update/slice/" target="_blank" rel="noreferrer">$push/$slice</a>, <a href="https://mongoosejs.com/docs/migrating_to_9.html" target="_blank" rel="noreferrer">Mongoose9 migration</a>.</p>',28)])])}const h=a(t,[["render",s]]);export{u as __pageData,h as default};
